@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const quarterColors=['#0A5694','#009DEE','#95D401','#FEC200'],serviceColors=['#2196F3','#9C27B0','#030363','#FF9800','#FFEB3B','#4CAF50'];const quarter=@json($quarter),services=@json($services),monthly=@json(collect(range(1,12))->map(fn($m)=>$rows->filter(fn($r)=>$r->tanggal_mulai->month===$m)->count())->values());const common={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}}};new Chart(document.getElementById('quarterChart'),{type:'bar',data:{labels:['Triwulan 1','Triwulan 2','Triwulan 3','Triwulan 4'],datasets:[{data:quarter,backgroundColor:quarterColors,borderRadius:8,borderSkipped:false}]},options:{...common,scales:{y:{beginAtZero:true,ticks:{precision:0},grid:{color:'#edf2f7'}},x:{grid:{display:false}}}}});const labels=Object.keys(services),counts=Object.values(services);new Chart(document.getElementById('serviceChart'),{type:'doughnut',data:{labels:labels.map((v,i)=>`${counts[i]} ${v}`),datasets:[{data:counts,backgroundColor:serviceColors,borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{boxWidth:12,padding:14}}}}});new Chart(document.getElementById('annualChart'),{type:'line',data:{labels:['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'],datasets:[{data:monthly,borderColor:'#0A5694',backgroundColor:'rgba(0,157,238,.18)',fill:true,tension:.35,pointRadius:4,pointBackgroundColor:'#009DEE'}]},options:{...common,scales:{y:{beginAtZero:true,ticks:{precision:0},grid:{color:'#edf2f7'}},x:{grid:{display:false}}}}});});</script>@endpush>


